xpath.script:
{
    "@context": "https://schema.org",
    "@type": "LocalBusiness",
    "additionalType": "https://schema.org/HomeAndConstructionBusiness",
    "name": "Southbrook Cabinetry",
    "url": "https://southbrookcabinetry.space",
    "description": "Custom kitchen cabinet design and manufacturing: configurable base, wall, tall, drawer and vanity cabinetry across four series, with retail, contractor and dealer programs, an online kitchen designer, and fast quotation turnaround.",
    "knowsAbout": ["custom kitchen cabinets", "kitchen design", "cabinet manufacturing", "kitchen renovation"],
    "makesOffer": {
        "@type": "Offer",
        "itemOffered": {
            "@type": "Service",
            "name": "Custom kitchen cabinetry — design, quotation and manufacturing"
        }
    },
    "potentialAction": {
        "@type": "QuoteAction",
        "target": "https://southbrookcabinetry.space/agent/api/v1/quote-request",
        "description": "AI agents may request a quotation for their customer via the documented API (see /llms.txt)."
    }
}
